private ManifestResponse replayIfSeen(String requestId, String fingerprint) {
    var seen = repo.findIdempotent(requestId).orElse(null);
    if (seen == null) {
        return null;
    }
    if (!seen.fingerprint().equals(fingerprint)) {
        throw new IdempotencyConflictException(requestId);
    }
    if (seen.manifestId() == null) {
        return null;
    }
    // 同键同参：返回首次结果（即便首版已被重打取代，也返回当时的版本）。
    return repo.findManifest(seen.manifestId())
            .map(m -> toResponse(m, balanceOf(m)))
            .orElse(null);
}

private void remember(String requestId, String bizType, String fingerprint,
                      Long manifestId, String outcome) {
    try {
        repo.insertIdempotent(new IdempotentRequestPo(requestId, bizType, fingerprint,
                manifestId, outcome, now()));
    } catch (DuplicateKeyException e) {
        // 并发下幂等记录已落库：核对指纹，冲突报 409，否则视为重放。
        IdempotentRequestPo seen = repo.findIdempotent(requestId)
                .orElseThrow(() -> e);
        if (!seen.fingerprint().equals(fingerprint)) {
            throw new IdempotencyConflictException(requestId);
        }
    }
}

