65	    @Transactional
66	    public ManifestResponse preplan(PreplanRequest req) {
67	        String fp = fingerprint(BIZ_PREPLAN, req.requestId(),
68	                req.flightNo() + "|" + req.flightDate() + "|" + req.aircraftType() + "|"
69	                        + req.aircraftRegistration() + "|" + norm(req.fuelKg()) + "|"
70	                        + norm(emptyIfNull(req.fuelArm())) + "|" + canonicalItems(req.items()));
71	        ManifestResponse replay = replayIfSeen(req.requestId(), fp);
72	        if (replay != null) {
73	            return replay;
74	        }
75	
76	        AircraftConfig config = repo.findConfig(req.aircraftType())
77	                .orElseThrow(() -> new NotFoundException("机型不存在: " + req.aircraftType()));
78	        if (req.fuelKg().signum() < 0) {
79	            throw new BusinessRuleException("加油量不得为负");
80	        }
81	        String flightKey = flightKey(req.flightNo(), req.flightDate());
82	        if (repo.findActiveManifestId(flightKey).isPresent()) {
83	            throw new BusinessRuleException("航班已存在有效舱单版本，同一航班同时刻仅允许一个有效版本");
84	        }
85	
86	        List<PayloadItemDto> items = req.items() == null ? List.of() : req.items();
87	        Balance calc = compute(config, items, req.fuelKg(),
88	                req.fuelArm() == null ? config.defaultFuelArm() : req.fuelArm());
89	        calc.assertValid();
90	
91	        ManifestPo po = new ManifestPo(null, flightKey, req.flightNo(), req.flightDate(),
92	                req.aircraftType(), req.aircraftRegistration(), 1,
93	                ManifestStatus.PREPARED.name(), null, req.requestId(), fp,
94	                calc.fuelKg, calc.fuelArm, calc.fuelMoment, calc.totals.passengerCount(),
95	                calc.totals.weightKg(), calc.totals.moment(), calc.zfw, calc.zfwMoment, calc.zfwCg,
96	                calc.tow, calc.towMoment, calc.towCg, 0, BigDecimal.ZERO, false, null, null, null);
97	        long id;
98	        try {
99	            id = repo.insertManifest(po);
100	            repo.insertActiveManifest(flightKey, id, 1);
101	        } catch (DuplicateKeyException e) {
102	            throw new BusinessRuleException("航班已存在有效舱单版本，同一航班同时刻仅允许一个有效版本");
103	        }
104	        for (PayloadItemDto item : items) {
105	            insertItem(id, item);
106	        }
107	        remember(req.requestId(), BIZ_PREPLAN, fp, id, "PREPARED");
108	        return toResponse(repo.findManifest(id).orElseThrow(), calc);
109	    }
