111	    // ============================ 值机 ============================
112	
113	    @Transactional
114	    public ManifestResponse checkin(String flightKey, CheckinRequest req) {
115	        String fp = fingerprint(BIZ_CHECKIN, req.requestId(),
116	                flightKey + "|" + canonicalItems(req.items()));
117	        ManifestResponse replay = replayIfSeen(req.requestId(), fp);
118	        if (replay != null) {
119	            return replay;
120	        }
121	        ManifestPo m = lockActive(flightKey);
122	        List<PayloadItemDto> items = req.items() == null ? List.of() : req.items();
123	
124	        if (ManifestStatus.CLOSED.name().equals(m.status())) {
125	            return lateChange(flightKey, m, "CHECK_IN", req.requestId(), fp,
126	                    "关闭后收到值机全量明细 " + items.size() + " 行，未写入舱单");
127	        }
128	        assertNotFrozen(m);
129	        if (!Set.of(ManifestStatus.PREPARED.name(), ManifestStatus.CHECK_IN.name()).contains(m.status())) {
130	            throw new BusinessRuleException("当前状态 " + m.status() + " 不允许值机上载，装载确认后请走 LMC");
131	        }
132	
133	        AircraftConfig config = configOf(m);
134	        Balance calc = compute(config, items, m.fuelKg(), m.fuelArm());
135	        calc.assertValid();
136	
137	        repo.deletePayloadItems(m.id());
138	        for (PayloadItemDto item : items) {
139	            insertItem(m.id(), item);
140	        }
141	        ManifestPo updated = withComputed(m, ManifestStatus.CHECK_IN.name(), calc, m.lmcDeltaPax(),
142	                m.lmcDeltaKg(), m.frozen(), m.closedAt());
143	        repo.updateComputedManifest(updated);
144	        remember(req.requestId(), BIZ_CHECKIN, fp, m.id(), ManifestStatus.CHECK_IN.name());
145	        return toResponse(repo.findManifest(m.id()).orElseThrow(), calc);
146	    }
147	
148	    // ============================ 装载确认 ============================
149	
150	    @Transactional
151	    public ManifestResponse loadConfirm(String flightKey, LoadConfirmRequest req) {
152	        String fp = fingerprint(BIZ_LOAD_CONFIRM, req.requestId(), flightKey);
153	        ManifestResponse replay = replayIfSeen(req.requestId(), fp);
154	        if (replay != null) {
155	            return replay;
156	        }
157	        ManifestPo m = lockActive(flightKey);
158	        if (ManifestStatus.LOADED.name().equals(m.status())
159	                || ManifestStatus.REVIEWED.name().equals(m.status())
160	                || ManifestStatus.CLOSED.name().equals(m.status())) {
161	            throw new BusinessRuleException("舱单已完成装载确认，不可重复确认");
162	        }
163	        if (!Set.of(ManifestStatus.PREPARED.name(), ManifestStatus.CHECK_IN.name()).contains(m.status())) {
164	            throw new BusinessRuleException("当前状态 " + m.status() + " 不允许装载确认");
165	        }
166	        repo.updateStatus(m.id(), ManifestStatus.LOADED.name());
167	        remember(req.requestId(), BIZ_LOAD_CONFIRM, fp, m.id(), ManifestStatus.LOADED.name());
168	        return toResponse(repo.findManifest(m.id()).orElseThrow(), balanceOf(m));
169	    }
170	
171	    // ============================ LMC ============================
172	
173	    @Transactional
174	    public ManifestResponse lmc(String flightKey, LmcRequest req) {
175	        String fp = fingerprint(BIZ_LMC, req.requestId(),
176	                flightKey + "|" + canonicalItems(req.deltaItems()));
177	        ManifestResponse replay = replayIfSeen(req.requestId(), fp);
178	        if (replay != null) {
179	            return replay;
180	        }
181	        ManifestPo m = lockActive(flightKey);
182	        List<PayloadItemDto> deltas = req.deltaItems() == null ? List.of() : req.deltaItems();
183	        BalanceCalculator.PayloadTotals deltaTotals = BalanceCalculator.sumPayload(deltas);
184	        int newDeltaPax = m.lmcDeltaPax() + deltaTotals.passengerCount();
185	        BigDecimal newDeltaKg = m.lmcDeltaKg().add(deltaTotals.weightKg());
186	
187	        if (ManifestStatus.CLOSED.name().equals(m.status())) {
188	            return lateChange(flightKey, m, "LMC", req.requestId(), fp,
189	                    "关闭后收到 LMC：人数增量 " + newDeltaPax + "，重量增量 " + newDeltaKg + "kg，未写入舱单");
190	        }
191	        assertNotFrozen(m);
192	        if (!ManifestStatus.LOADED.name().equals(m.status())) {
193	            throw new BusinessRuleException("仅装载确认后的舱单可进行 LMC，当前状态 " + m.status());
194	        }
195	
196	        AircraftConfig config = configOf(m);
197	        boolean withinLimit = BalanceCalculator.withinLmcLimit(newDeltaPax, newDeltaKg);
198	
199	        if (withinLimit) {
200	            // 限额内：在当前版本原地追加增量行，累计增量落在 ±5 人 / ±500kg 内。
201	            List<PayloadItemPo> existing = repo.findPayloadItems(m.id());
202	            List<PayloadItemDto> projected = new ArrayList<>(toDtos(existing));
203	            projected.addAll(deltas);
204	            Balance calc = compute(config, projected, m.fuelKg(), m.fuelArm());
205	            calc.assertValid();
206	            for (PayloadItemDto d : deltas) {
207	                insertItem(m.id(), d);
208	            }
209	            ManifestPo updated = withComputed(m, ManifestStatus.LOADED.name(), calc, newDeltaPax,
210	                    newDeltaKg, false, null);
211	            repo.updateComputedManifest(updated);
212	            remember(req.requestId(), BIZ_LMC, fp, m.id(), "LMC_IN_PLACE");
213	            return toResponse(repo.findManifest(m.id()).orElseThrow(), calc);
214	        }
215	
216	        // 超限：重打新版本（全量明细 = 旧明细 + 本次增量），旧版本 SUPERSEDED，版本链接续。
217	        List<PayloadItemDto> projected = new ArrayList<>(toDtos(repo.findPayloadItems(m.id())));
218	        projected.addAll(deltas);
219	        Balance calc = compute(config, projected, m.fuelKg(), m.fuelArm());
220	        calc.assertValid();
221	
222	        int newVersion = m.versionNo() + 1;
223	        ManifestPo reprint = new ManifestPo(null, flightKey, m.flightNo(), m.flightDate(),
224	                m.aircraftType(), m.aircraftRegistration(), newVersion,
225	                ManifestStatus.LOADED.name(), m.id(), req.requestId(), fp,
226	                calc.fuelKg, calc.fuelArm, calc.fuelMoment, calc.totals.passengerCount(),
227	                calc.totals.weightKg(), calc.totals.moment(), calc.zfw, calc.zfwMoment, calc.zfwCg,
228	                calc.tow, calc.towMoment, calc.towCg, 0, BigDecimal.ZERO, false, null, null, null);
229	        long newId = repo.insertManifest(reprint);
230	        for (PayloadItemDto item : projected) {
231	            insertItem(newId, item);
232	        }
233	        repo.updateStatus(m.id(), ManifestStatus.SUPERSEDED.name());
234	        repo.updateActiveManifest(flightKey, newId, newVersion);
235	        remember(req.requestId(), BIZ_LMC, fp, newId, "REPRINTED_V" + newVersion);
236	        return toResponse(repo.findManifest(newId).orElseThrow(), calc);
237	    }
